"""KyberPad controller metadata and v3.0 INI export helpers.

The controller YAML ``kyberpad`` mapping is the single source of truth for:

* analog ladder decoding used by :mod:`puddle_joy`;
* logical names for the synthetic KyberPad buttons;
* button colors used by the KyberPad application; and
* the PWM values exported to a KyberPad Config v3.0 INI file.

The runtime only consumes the ladder and logical button names.  The visual and
PWM metadata is retained for the web editor/export path.
"""

from __future__ import annotations

from pathlib import Path
from typing import Any, Dict, List, Mapping, MutableMapping, Sequence
import re


KYBERPAD_BUTTON_COUNT = 45
KYBERPAD_PWM_COUNT = 15

DEFAULT_BACKGROUND = "#A5A2A5"
DEFAULT_TEXT_COLOR = "#000000"
DEFAULT_PRESSED_COLOR = "#FFFFFF"

_COLOR_RE = re.compile(r"^#[0-9A-Fa-f]{6}$")


def _color(value: Any, *, label: str, default: str) -> str:
    if value is None or str(value).strip() == "":
        return default
    text = str(value).strip()
    if not _COLOR_RE.fullmatch(text):
        raise ValueError(f"kyberpad {label} must be a #RRGGBB color")
    return text.upper()


def _label(value: Any, *, index: int) -> str:
    text = str(value if value is not None else "")
    if "\r" in text or "\n" in text:
        raise ValueError(f"kyberpad button {index:02d} label must be one line")
    return text


def normalize_general(kyberpad: Mapping[str, Any]) -> Dict[str, str]:
    raw = kyberpad.get("general") or {}
    if not isinstance(raw, Mapping):
        raise ValueError("kyberpad.general must be a mapping")
    background = _color(
        raw.get("background"),
        label="general.background",
        default=DEFAULT_BACKGROUND,
    )
    text_color = _color(
        raw.get("text_color"),
        label="general.text_color",
        default=DEFAULT_TEXT_COLOR,
    )
    pressed_color = _color(
        raw.get("pressed_color"),
        label="general.pressed_color",
        default=DEFAULT_PRESSED_COLOR,
    )
    return {
        "background": background,
        "text_color": text_color,
        "pressed_color": pressed_color,
    }


def normalize_buttons(
    kyberpad: Mapping[str, Any],
    *,
    pad_to: int = KYBERPAD_BUTTON_COUNT,
) -> List[Dict[str, str]]:
    general = normalize_general(kyberpad)
    raw_buttons = kyberpad.get("buttons")
    if raw_buttons is None:
        raw_buttons = []
    if not isinstance(raw_buttons, list):
        raise ValueError("kyberpad.buttons must be a list")
    if len(raw_buttons) > pad_to:
        raise ValueError(f"kyberpad.buttons may contain at most {pad_to} entries")

    result: List[Dict[str, str]] = []
    for offset in range(pad_to):
        index = offset + 1
        entry = raw_buttons[offset] if offset < len(raw_buttons) else {"": None}
        if isinstance(entry, str):
            # Keep parsing friendly for hand-written definitions, while the
            # generated built-ins use the canonical one-key mapping form.
            label = _label(entry, index=index)
            attrs: Mapping[str, Any] = {}
        elif isinstance(entry, Mapping):
            if len(entry) != 1:
                raise ValueError(
                    f"kyberpad.buttons[{offset}] must be a one-key mapping whose key is the label"
                )
            label_value, raw_attrs = next(iter(entry.items()))
            label = _label(label_value, index=index)
            if raw_attrs is None:
                attrs = {}
            elif isinstance(raw_attrs, Mapping):
                attrs = raw_attrs
            else:
                raise ValueError(
                    f"kyberpad.buttons[{offset}] attributes must be a mapping or null"
                )
        else:
            raise ValueError(
                f"kyberpad.buttons[{offset}] must be a string or one-key mapping"
            )

        event = str(attrs.get("event") if "event" in attrs else label.casefold()).strip()
        if "\r" in event or "\n" in event:
            raise ValueError(f"kyberpad button {index:02d} event must be one line")

        result.append({
            "label": label,
            "event": event,
            "background": _color(
                attrs.get("background"),
                label=f"button {index:02d} background",
                default=general["background"],
            ),
            "text_color": _color(
                attrs.get("text_color"),
                label=f"button {index:02d} text_color",
                default=general["text_color"],
            ),
        })
    return result


def normalize_pwm(kyberpad: Mapping[str, Any]) -> Dict[str, Any]:
    raw = kyberpad.get("pwm")
    if not isinstance(raw, Mapping):
        raise ValueError("kyberpad.pwm must be a mapping")
    values = raw.get("values")
    if not isinstance(values, Sequence) or isinstance(values, (str, bytes, bytearray)):
        raise ValueError("kyberpad.pwm.values must be a list of 15 integers")
    if len(values) != KYBERPAD_PWM_COUNT:
        raise ValueError(
            f"kyberpad.pwm.values must contain exactly {KYBERPAD_PWM_COUNT} integers"
        )
    try:
        normalized = [int(value) for value in values]
        released = int(raw.get("released"))
    except (TypeError, ValueError) as exc:
        raise ValueError("kyberpad PWM values and released must be integers") from exc
    for index, value in enumerate(normalized, start=1):
        if not 0 <= value <= 4095:
            raise ValueError(f"kyberpad PWM value {index:02d} must be between 0 and 4095")
    if not 0 <= released <= 4095:
        raise ValueError("kyberpad.pwm.released must be between 0 and 4095")
    return {"values": normalized, "released": released}


def validate_kyberpad(kyberpad: Any, *, require_export_fields: bool = False) -> Dict[str, Any]:
    if not isinstance(kyberpad, Mapping):
        raise ValueError("controller kyberpad must be a mapping")

    normalized: Dict[str, Any] = dict(kyberpad)

    sequence = kyberpad.get("sequence")
    if sequence is not None:
        if not isinstance(sequence, list) or not sequence:
            raise ValueError("kyberpad.sequence must be a non-empty list")
        try:
            normalized["sequence"] = [int(value) for value in sequence]
        except (TypeError, ValueError) as exc:
            raise ValueError("kyberpad.sequence must contain integers") from exc

    for key in ("match_tolerance", "idle_value", "idle_tolerance", "button_base"):
        if key in kyberpad and kyberpad.get(key) is not None:
            try:
                normalized[key] = int(kyberpad.get(key))
            except (TypeError, ValueError) as exc:
                raise ValueError(f"kyberpad.{key} must be an integer") from exc

    if "shift_button" in kyberpad:
        normalized["shift_button"] = str(kyberpad.get("shift_button") or "")

    if "decode_axis" in kyberpad:
        decode_axis = kyberpad.get("decode_axis")
        if not isinstance(decode_axis, bool):
            raise ValueError("kyberpad.decode_axis must be a boolean")
        normalized["decode_axis"] = decode_axis

    if "general" in kyberpad or "buttons" in kyberpad or require_export_fields:
        normalized["general"] = normalize_general(kyberpad)
        normalized["buttons"] = normalize_buttons(kyberpad)

    if "pwm" in kyberpad or require_export_fields:
        normalized["pwm"] = normalize_pwm(kyberpad)

    return normalized


def synthetic_button_map(kyberpad: Any, *, default_base: int = 1000) -> Dict[int, str]:
    """Return non-empty synthetic button labels defined under ``kyberpad``.

    If ``kyberpad.buttons`` is absent, return an empty mapping so existing
    controller definitions that still place synthetic buttons in ``buttons``
    remain untouched.  Once the list exists it is authoritative, including
    empty slots.
    """
    if not isinstance(kyberpad, Mapping) or "buttons" not in kyberpad:
        return {}
    try:
        base = int(kyberpad.get("button_base", default_base))
    except (TypeError, ValueError):
        base = int(default_base)
    buttons = normalize_buttons(kyberpad)
    return {
        base + index: item["event"]
        for index, item in enumerate(buttons, start=1)
        if item["event"]
    }


def merge_synthetic_button_map(
    physical_buttons: MutableMapping[int, Any],
    kyberpad: Any,
    *,
    default_base: int = 1000,
) -> Dict[int, Any]:
    """Return one button map with ``kyberpad.buttons`` as synthetic authority."""
    merged: Dict[int, Any] = dict(physical_buttons)
    if not isinstance(kyberpad, Mapping) or "buttons" not in kyberpad:
        return merged
    try:
        base = int(kyberpad.get("button_base", default_base))
    except (TypeError, ValueError):
        base = int(default_base)
    for index in range(1, KYBERPAD_BUTTON_COUNT + 1):
        merged.pop(base + index, None)
    merged.update(synthetic_button_map(kyberpad, default_base=default_base))
    return merged


def export_ini(kyberpad: Any) -> str:
    normalized = validate_kyberpad(kyberpad, require_export_fields=True)
    general = normalized["general"]
    buttons = normalized["buttons"]
    pwm = normalized["pwm"]

    lines = [
        "# Kyberpad Config v3.0",
        "# Generated by Kyberpad. Colors are #RRGGBB.",
        "",
        "[General]",
        f"pressed_color = {general['pressed_color']}",
        "",
    ]
    for index, button in enumerate(buttons, start=1):
        lines.extend([
            f"[Button {index:02d}]",
            f"label = {button['label']}",
            f"background = {button['background']}",
            f"text_color = {button['text_color']}",
            "",
        ])

    lines.append("[PWM]")
    for index, value in enumerate(pwm["values"], start=1):
        lines.append(f"{index:02d} = {value}")
    lines.append(f"released = {pwm['released']}")
    lines.append("")
    return "\n".join(lines)


def export_filename(controller_filename: str, controller_name: str = "") -> str:
    stem = Path(str(controller_filename or "controller")).stem
    safe_stem = re.sub(r"[^A-Za-z0-9._-]+", "-", stem).strip("-._") or "controller"
    return f"{safe_stem}-kyberpad.ini"
